pub fn parse_part(json: &str) -> Result<Part, DecodeError> {
    wire::parse(json, decode_part)
}

/// Serializes a Part to wire JSON text.
pub fn serialize_part(value: &Part) -> String {
    encode_part(value).to_string()
}

