/// Decode-then-encode by type name. Used only by the shared conformance runner.
pub fn conformance_round_trip(type_name: &str, value: &Value) -> Option<Result<Value, DecodeError>> {
    match type_name {
        "TransferMethod" => Some(decode_transfer_method(value, "$").map(|decoded| encode_transfer_method(&decoded))),
        "TransferResponseKind" => Some(decode_transfer_response_kind(value, "$").map(|decoded| encode_transfer_response_kind(&decoded))),
        "TransferCredentials" => Some(decode_transfer_credentials(value, "$").map(|decoded| encode_transfer_credentials(&decoded))),
        "Part" => Some(decode_part(value, "$").map(|decoded| encode_part(&decoded))),
        "TransferBody" => Some(decode_transfer_body(value, "$").map(|decoded| encode_transfer_body(&decoded))),
        "TransferRequest" => Some(decode_transfer_request(value, "$").map(|decoded| encode_transfer_request(&decoded))),
        "TransferFailureReason" => Some(decode_transfer_failure_reason(value, "$").map(|decoded| encode_transfer_failure_reason(&decoded))),
        "TransferResult" => Some(decode_transfer_result(value, "$").map(|decoded| encode_transfer_result(&decoded))),
        "TransferDirection" => Some(decode_transfer_direction(value, "$").map(|decoded| encode_transfer_direction(&decoded))),
        "TransferFact" => Some(decode_transfer_fact(value, "$").map(|decoded| encode_transfer_fact(&decoded))),
        _ => None,
    }
}
